        return board_lines

    # Determine movement direction
    if action == 'UP':
        dr, dc = -1, 0
    elif action == 'DOWN':
        dr, dc = 1, 0
    elif action == 'LEFT':
        dr, dc = 0, -1
    elif action == 'RIGHT':
        dr, dc = 0, 1
    else:
