            old_values[(r, c)] = board[r][c]

        for (r, c) in push_objects:
            board[r][c] = 'w'

        for (r, c) in push_objects:
            nr, nc = r + dr, c + dc
            val = old_values[(r, c)]
            if val == 'r':
                board[nr][nc] = 'O'
            elif val == 'O':
                board[nr][nc] = 'r'
            elif val == 'N':
                board[nr][nc] = 'N'
            elif val == 'W':
                board[nr][nc] = 'W'
            else:
                board[nr][nc] = val

    # Move player
    player_old = {}
    for (r, c) in player_cells:
        player_old[(r, c)] = board[r][c]

    for (r, c) in player_cells:
        board[r][c] = 'w'

    for (r, c) in player_cells:
        nr, nc = r + dr, c + dc
        board[nr][nc] = 'P'

    # Turn rightmost W in row 63 to c
    for c in range(63, -1, -1):
        if board[63][c] == 'W':
            board[63][c] = 'c'
            break

    return [''.join(row) for row in board]
